 public void TestNativeEye(int index){var r=GetItemRectangle(index);IntPtr point=new IntPtr(((r.Top+r.Height/2)<<16)|15);SendMessage(Handle,0x201,new IntPtr(1),point);SendMessage(Handle,0x202,IntPtr.Zero,point);}
